/* ─── MENU ─── */
function Menu({ open, onClose, onNav }) {
  const [svcOpen, setSvcOpen] = useState(false);

  const subPages = [
    { label:"Bike Servicing Packages", page:"packages" },
    { label:"Full-Service (Full-sus MTB)", page:"full-service" },
    { label:"Custom Bike-Build", page:"bike-build" },
    { label:"Custom Wheel-Build", page:"wheel-build" },
    { label:"MTB Training & Guiding", page:"training" },
  ];

  const navTo = (page) => { onNav(page); onClose(); setSvcOpen(false); };

  return (
    <>
      <div className={`tp-menu-overlay ${open ? "open" : ""}`} onClick={onClose} />
      <div className={`tp-menu-drawer ${open ? "open" : ""}`}>
        <div className="tp-menu-head">
          <div className="tp-menu-logo"><img src="data:image/png;base64," alt="TRAIL+" style={{ height:"22px", width:"auto", display:"block", mixBlendMode:"lighten" }} /></div>
          <div className="tp-menu-close" onClick={onClose}>✕</div>
        </div>

        <div className="tp-menu-section">
          <div className="tp-menu-section-label">Navigation</div>

          {/* Services with sub-menu */}
          <div className="tp-menu-item" onClick={() => setSvcOpen(v => !v)}>
            <span className="tp-menu-item-label">Services</span>
            <span className="tp-menu-item-arrow">{svcOpen ? "↑" : "↓"}</span>
          </div>
          {svcOpen && (
            <div className="tp-menu-sub">
              {subPages.map(sp => (
                <div key={sp.page} className="tp-menu-sub-item" onClick={() => navTo(sp.page)}>
                  <div className="tp-menu-sub-dot" />
                  <span className="tp-menu-sub-label">{sp.label}</span>
                </div>
              ))}
            </div>
          )}

          <div className="tp-menu-item" onClick={() => navTo("home")}>
            <span className="tp-menu-item-label">Home</span>
            <span className="tp-menu-item-arrow">→</span>
          </div>
          <div className="tp-menu-item" onClick={() => { window.open("https://trailplus.sg/#brands","_blank"); onClose(); }}>
            <span className="tp-menu-item-label">Brands</span>
            <span className="tp-menu-item-arrow">→</span>
          </div>
          <div className="tp-menu-item" onClick={() => { window.open("https://www.instagram.com/trailplus.sg","_blank"); onClose(); }}>
            <span className="tp-menu-item-label">Follow Us</span>
            <span className="tp-menu-item-arrow">→</span>
          </div>
          <div className="tp-menu-item" onClick={() => { window.open("https://trailplus.sg/#contact_us","_blank"); onClose(); }}>
            <span className="tp-menu-item-label">Contact Us</span>
            <span className="tp-menu-item-arrow">→</span>
          </div>
          <div className="tp-menu-item" onClick={() => { window.open("https://trailplus.sg/directions/","_blank"); onClose(); }}>
            <span className="tp-menu-item-label">Directions</span>
            <span className="tp-menu-item-arrow">→</span>
          </div>
        </div>

        <a href="https://trailplus.sg/servicing-request-form/" className="tp-menu-cta" target="_blank" rel="noreferrer">
          BOOK A SERVICE <span>→</span>
        </a>
      </div>
    </>
  );
}

/* ─── MAIN APP ─── */
export default function TrailPlusApp() {
  const [page, setPage] = useState("home");
  const [menuOpen, setMenuOpen] = useState(false);

  const navTo = (p) => { setPage(p); window.scrollTo?.(0, 0); };

  const renderPage = () => {
    switch (page) {
      case "packages":   return <PageServicePackages onBack={() => navTo("home")} />;
      case "full-service": return <PageFullService onBack={() => navTo("home")} />;
      case "bike-build": return <PageBikeBuild onBack={() => navTo("home")} />;
      case "wheel-build": return <PageWheelBuild onBack={() => navTo("home")} />;
      case "training":   return <PageTraining onBack={() => navTo("home")} />;
      default:           return <HomePage onNav={navTo} />;
    }
  };

  return (
    <div style={{ background: "#050505", minHeight:"100vh" }}>
      <style>{CSS}</style>
      <div className="tp">
        {/* NAV */}
        <nav className="tp-nav">
          <div className="tp-nav-logo" onClick={() => navTo("home")}>
            <img src="data:image/png;base64," alt="TRAIL+" style={{ height:"28px", width:"auto", display:"block", background:"transparent", mixBlendMode:"lighten" }} />
            <div className="tp-logo-sub">MTB PERFORMANCE LAB</div>
          </div>
          <div className="tp-nav-links" style={{display:"none"}}>
            <span className="tp-nav-link" onClick={() => navTo("packages")}>Servicing</span>
            <span className="tp-nav-link" onClick={() => navTo("full-service")}>Full Service</span>
            <span className="tp-nav-link" onClick={() => navTo("bike-build")}>Custom Builds</span>
            <span className="tp-nav-link" onClick={() => navTo("wheel-build")}>Wheel Builds</span>
            <span className="tp-nav-link" onClick={() => navTo("training")}>Training</span>
            <a href="https://trailplus.sg/servicing-request-form/" className="tp-nav-cta" target="_blank" rel="noreferrer">BOOK NOW</a>
          </div>
          <div className="tp-ham" onClick={() => setMenuOpen(true)}>
            <span /><span /><span />
          </div>
        </nav>

        {/* MENU */}
        <Menu open={menuOpen} onClose={() => setMenuOpen(false)} onNav={navTo} />

        {/* PAGE CONTENT */}
        {renderPage()}
      </div>
    </div>
  );
}
